const STORAGE_KEY = "circuitos-lab-state-v1";
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];

const defaultCircuit = [
  {id:"c1",type:"V",name:"Vs",value:10,unit:"V",n1:"N1",n2:"0"},
  {id:"c2",type:"R",name:"R1",value:330,unit:"Ω",n1:"N1",n2:"N2"},
  {id:"c3",type:"R",name:"R2",value:330,unit:"Ω",n1:"N2",n2:"0"},
  {id:"c4",type:"R",name:"R3",value:330,unit:"Ω",n1:"N2",n2:"N3"},
  {id:"c5",type:"R",name:"RL",value:330,unit:"Ω",n1:"N3",n2:"0"}
];

function initialState(){
  try { const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||"null"); if(raw&&typeof raw==="object") return {...raw,components:Array.isArray(raw.components)?raw.components:defaultCircuit.map(x=>({...x})),completed:raw.completed||{},chapterResults:raw.chapterResults||{},drafts:raw.drafts||{},bestScores:raw.bestScores||{},exam:raw.exam||{topic:"equivalentes",started:false,finished:false,q:0,selected:null,answers:[]}}; } catch(e){}
  return {view:"home",activeChapter:"fundamentos",components:defaultCircuit.map(x=>({...x})),lastSolution:null,completed:{},chapterResults:{},drafts:{},bestScores:{},savedCircuit:null,exam:{topic:"equivalentes",started:false,finished:false,q:0,selected:null,answers:[]},examAttempts:0};
}
const state=initialState();
const saveState=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}};
const esc=(s)=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const nodeNames=["0","N1","N2","N3"];
const nodeOptions=(selected)=>nodeNames.map(n=>`<option value="${n}" ${n===selected?"selected":""}>${n==="0"?"GND":n}</option>`).join("");
const chapters=[
  {id:"fundamentos",title:"Magnitudes y unidades",short:"Fundamentos",icon:"◉",minutes:8,level:"INICIO",desc:"Aprende a leer los valores eléctricos y sus unidades.",formula:"V = energía / carga     ·     I = carga / tiempo",theory:`<p>El <b>voltaje (V)</b> es la diferencia de potencial entre dos puntos. La <b>corriente (I)</b> describe cuánta carga atraviesa una sección por segundo. La <b>resistencia (R)</b> limita el paso de corriente y se mide en ohmios (Ω).</p><p>En un circuito ideal usamos también la potencia, que indica la rapidez con la que un elemento entrega o absorbe energía.</p><ul><li>Voltaje: voltios (V) · corriente: amperios (A) · resistencia: ohmios (Ω)</li><li>Prefijos: m = 10⁻³, μ = 10⁻⁶, k = 10³, M = 10⁶</li><li>Convención pasiva: si la corriente entra por el terminal positivo, P = VI > 0 significa potencia absorbida.</li></ul>`,callout:`Antes de operar, convierte todo a unidades compatibles. Por ejemplo, 4.7 kΩ = 4700 Ω y 25 mA = 0.025 A.`,question:`Una resistencia de 1 kΩ está conectada a una fuente de 12 V. ¿Qué corriente circula? Escribe el resultado en mA.`,unit:"mA",answer:12,hints:["Convierte primero 1 kΩ a ohmios: 1000 Ω.","Usa I = V / R y convierte amperios a miliamperios."],solution:["R = 1 kΩ = 1000 Ω","I = V/R = 12/1000 = 0.012 A","0.012 A × 1000 = 12 mA"]},
  {id:"ohm",title:"Ley de Ohm",short:"Ley de Ohm",icon:"↗",minutes:10,level:"INICIO",desc:"Relaciona voltaje, corriente y resistencia en cada elemento.",formula:"V = I · R     ·     I = V / R     ·     R = V / I",theory:`<p>La ley de Ohm conecta las tres magnitudes de un elemento resistivo lineal. Si conoces dos, despejas la tercera. Respeta la unidad elegida: V en voltios, I en amperios y R en ohmios.</p><p>Para un resistor de 220 Ω con 9.9 V entre terminales:</p><div class="formula-block">I = 9.9 V / 220 Ω = 0.045 A = 45 mA</div><p>La relación es local: primero identifica el voltaje que realmente cae en el resistor, no necesariamente el voltaje de toda la fuente.</p>`,callout:`Revisión rápida: si R se mantiene y duplicas V, I también se duplica. Si V se mantiene y duplicas R, I se reduce a la mitad.`,question:`En un resistor de 220 Ω hay una caída de 9.9 V. ¿Cuál es la corriente en mA?`,unit:"mA",answer:45,hints:["Identifica V = 9.9 V y R = 220 Ω.","Aplica I = V/R. Multiplica el resultado en A por 1000 para obtener mA."],solution:["I = V/R = 9.9/220 = 0.045 A","I = 0.045 × 1000 = 45 mA"]},
  {id:"serie",title:"Resistencias en serie y paralelo",short:"Serie y paralelo",icon:"⇄",minutes:12,level:"PRÁCTICA",desc:"Simplifica redes y reconoce qué magnitud comparten.",formula:"Serie: Rₑq = ΣRᵢ     ·     Paralelo: 1/Rₑq = Σ(1/Rᵢ)",theory:`<p>En <b>serie</b>, los elementos comparten la misma corriente y sus resistencias se suman. En <b>paralelo</b>, las ramas comparten el mismo voltaje; para dos resistencias puedes usar el producto entre suma.</p><div class="formula-block">R₁ ∥ R₂ = (R₁ · R₂) / (R₁ + R₂)</div><p>Una buena revisión es comparar el equivalente: en paralelo debe ser menor que la resistencia más pequeña de la rama.</p>`,callout:`Antes de reducir un circuito, marca los nodos. Dos elementos están en paralelo solo si ambos terminales se conectan a los mismos dos nodos.`,question:`Tres resistencias de 100 Ω, 220 Ω y 330 Ω están conectadas en serie. Calcula la resistencia equivalente en Ω.`,unit:"Ω",answer:650,hints:["En serie, no uses el producto entre la suma.","Suma las tres resistencias: 100 + 220 + 330."],solution:["Rₑq = 100 + 220 + 330","Rₑq = 650 Ω"]},
  {id:"nodos",title:"Leyes de Kirchhoff y nodos",short:"Nodos",icon:"⌘",minutes:14,level:"PRÁCTICA",desc:"Plantea ecuaciones de corriente y encuentra voltajes nodales.",formula:"Σ Iₖ = 0     ·     I = (Vₐ − Vᵦ) / R",theory:`<p>La ley de corrientes de Kirchhoff (LCK) dice que la suma algebraica de corrientes en un nodo es cero. Elige un nodo de referencia y expresa cada rama con los voltajes nodales.</p><p>Para una rama resistiva entre nodos a y b: <span class="mono">Iₐᵦ = (Vₐ − Vᵦ)/R</span>. Mantén una convención de signos en toda la ecuación.</p><div class="formula-block">En un nodo: (Vₙ − Vₛ)/R₁ + Vₙ/R₂ = 0</div><p>Los nodos principales reducen el número de incógnitas; no necesitas calcular cada corriente de rama antes de plantear la ecuación.</p>`,callout:`Tip: si obtienes un voltaje negativo, suele indicar que la polaridad real es opuesta a la que asumiste. La solución puede seguir siendo válida.`,question:`Una fuente de 12 V alimenta R₁ = 1 kΩ en serie con R₂ = 2 kΩ. ¿Cuál es el voltaje del nodo entre ambas resistencias respecto a tierra?`,unit:"V",answer:8,hints:["El divisor de voltaje da Vn = Vs · R₂/(R₁ + R₂).","Sustituye 12 · 2000/(1000 + 2000)."],solution:["Vₙ = 12 · 2000/(1000 + 2000)","Vₙ = 8 V respecto a tierra"]},
  {id:"mallas",title:"Análisis de mallas",short:"Mallas",icon:"▱",minutes:14,level:"PRÁCTICA",desc:"Resuelve corrientes de lazo usando KVL y supermallas.",formula:"Σ Vₖ = 0     ·     V_R = R · I",theory:`<p>La ley de voltajes de Kirchhoff (LVK) establece que la suma algebraica de voltajes a lo largo de una trayectoria cerrada es cero. En el método de mallas se asigna una corriente a cada lazo independiente.</p><p>En una resistencia compartida por dos mallas, la caída en la dirección de la malla 1 es <span class="mono">R(I₁ − I₂)</span>. Escribe el sentido de recorrido antes de sumar caídas y elevaciones.</p><div class="formula-block">R₁I₁ + R₃(I₁ − I₂) = Vₛ</div>`,callout:`Si una fuente de corriente está entre dos mallas, usa una supermalla y agrega la ecuación que relaciona I₁ e I₂.`,question:`Una malla simple tiene una fuente de 15 V y resistencias en serie de 1 kΩ y 2 kΩ. ¿Cuál es la corriente de malla en mA?`,unit:"mA",answer:5,hints:["Suma las resistencias porque están en serie.","Aplica I = 15 V / 3000 Ω y convierte a mA."],solution:["Rₑq = 1000 + 2000 = 3000 Ω","I = 15/3000 = 0.005 A = 5 mA"]},
  {id:"thevenin",title:"Equivalente de Thévenin",short:"Thévenin",icon:"⊙",minutes:16,level:"AVANZADO",desc:"Reemplaza una red lineal por una fuente y una resistencia.",formula:"Vₜₕ = V circuito abierto     ·     Rₜₕ = R vista desde la carga",theory:`<p>Desde las terminales de la carga, cualquier red lineal de fuentes y resistencias puede reemplazarse por una fuente ideal de voltaje <b>Vₜₕ</b> en serie con <b>Rₜₕ</b>.</p><ul><li>Retira la carga y calcula el voltaje en circuito abierto: ese es Vₜₕ.</li><li>Desactiva fuentes independientes (fuentes de voltaje a corto; fuentes de corriente a circuito abierto) y calcula la resistencia vista desde las terminales.</li><li>Reconecta la carga para encontrar la corriente: Iᴸ = Vₜₕ/(Rₜₕ + Rᴸ).</li></ul>`,callout:`Una fuente dependiente no se apaga. Para hallar la resistencia equivalente con fuentes dependientes, usa una fuente de prueba en las terminales.`,question:`Vₜₕ = 12 V y Rₜₕ = 1 kΩ ∥ 2 kΩ. ¿Cuánto vale Rₜₕ en Ω?`,unit:"Ω",answer:666.67,hints:["Para dos resistencias en paralelo, Rₜₕ = (R₁R₂)/(R₁+R₂).","Calcula 1000×2000/3000."],solution:["Rₜₕ = (1000 · 2000)/(1000 + 2000)","Rₜₕ = 666.67 Ω (aprox.)"]},
  {id:"norton",title:"Equivalente de Norton",short:"Norton",icon:"⇌",minutes:18,level:"AVANZADO",desc:"Encuentra la fuente de corriente equivalente y calcula una carga.",formula:"Iₙ = I cortocircuito     ·     Rₙ = R vista desde la carga",theory:`<p>El equivalente de Norton sustituye una red lineal por una fuente ideal de corriente <b>Iₙ</b> en paralelo con una resistencia <b>Rₙ</b>. Se observa la red desde los terminales donde se conecta la carga.</p><ul><li>Retira Rᴸ y cortocircuita las terminales para obtener Iₙ.</li><li>Desactiva la fuente independiente y calcula Rₙ vista desde las terminales.</li><li>Conecta Rᴸ: Iᴸ = Iₙ · Rₙ/(Rₙ + Rᴸ).</li></ul><div class="lesson-callout"><b>Ejemplo aplicado:</b> para Vs = 10 V y cuatro resistencias de 330 Ω, al mirar desde RL: Rₙ = R3 + (R1 ∥ R2) = 495 Ω; el cortocircuito de salida produce Iₙ ≈ 10.10 mA.</div><p>Con RL = 330 Ω, resulta Iᴸ ≈ 6.06 mA y Vᴸ ≈ 2.00 V. Este circuito de práctica está basado en el reporte de referencia que compartiste.</p>`,callout:`Comprueba la conversión entre modelos: Vₜₕ = IₙRₙ y Rₜₕ = Rₙ. Si no coinciden, revisa el sentido de Iₙ y las terminales.`,question:`En el ejemplo de 10 V y cuatro resistencias de 330 Ω, ¿cuánto vale la corriente de Norton Iₙ en mA?`,unit:"mA",answer:10.10,hints:["Cortocircuita las terminales de salida: R2 y R3 quedan en paralelo (165 Ω).","I total = 10/(330 + 165) = 20.20 mA; el voltaje en el paralelo es 3.33 V. Halla la corriente por R3."],solution:["R₂ ∥ R₃ = 165 Ω; Iₜ = 10/(330 + 165) = 20.20 mA","V en el paralelo = Iₜ · 165 = 3.33 V","Iₙ = 3.33/330 = 0.01010 A ≈ 10.10 mA"]},
  {id:"ac",title:"Corriente alterna y fasores",short:"CA y fasores",icon:"∿",minutes:16,level:"AVANZADO",desc:"Trabaja con impedancia, reactancia y ángulos de fase.",formula:"Z_R = R     ·     Z_L = jωL     ·     Z_C = 1/(jωC)",theory:`<p>En estado sinusoidal, los fasores convierten derivadas e integrales en operaciones algebraicas complejas. La impedancia generaliza la resistencia y relaciona los fasores de voltaje y corriente.</p><p>Para una resistencia de 300 Ω en serie con una inductancia cuya reactancia es j400 Ω: <span class="mono">Z = 300 + j400 Ω</span>.</p><div class="formula-block">|Z| = √(300² + 400²) = 500 Ω</div><p>El ángulo de la impedancia es <span class="mono">atan2(400, 300) ≈ 53.13°</span>; la corriente queda atrasada respecto al voltaje en una carga inductiva.</p>`,callout:`Usa la frecuencia angular ω = 2πf. Para capacitores, la reactancia disminuye cuando la frecuencia aumenta.`,question:`R = 300 Ω y Xᴸ = 400 Ω en serie. ¿Cuál es la magnitud |Z| en Ω?`,unit:"Ω",answer:500,hints:["La magnitud es √(R² + Xᴸ²).","Calcula √(300² + 400²)."],solution:["|Z| = √(300² + 400²)","|Z| = √250000 = 500 Ω"]}
];

const examBanks={
  fundamentos:{title:"Fundamentos y ley de Ohm",meta:"Magnitudes, unidades y potencia",questions:[
    {q:"¿Qué corriente atraviesa una resistencia de 2 kΩ conectada a 10 V?",options:["5 mA","20 mA","0.2 mA","5 A"],correct:0,why:"I = V/R = 10/2000 = 0.005 A = 5 mA. El prefijo kilo equivale a 1000 y después de obtener amperios se multiplica por 1000 para expresarlos en mA.",wrong:"La resistencia debe convertirse a 2000 Ω. Un error frecuente es no convertir kΩ antes de dividir."},
    {q:"Una resistencia de 4 Ω conduce 3 A. ¿Qué potencia absorbe?",options:["12 W","36 W","1.33 W","7 W"],correct:1,why:"P = I²R = 3² × 4 = 36 W. También puedes comprobarlo con V = IR = 12 V y P = VI = 36 W.",wrong:"Para esta pareja de datos usa P = I²R, no P = I/R. La corriente se eleva al cuadrado."},
    {q:"Si el voltaje permanece constante y la resistencia se duplica, la corriente…",options:["Se reduce a la mitad","Se duplica","No cambia","Se cuadruplica"],correct:0,why:"Por I = V/R, con V constante la corriente es inversamente proporcional a R. Duplicar R divide I entre dos.",wrong:"La relación entre corriente y resistencia es inversa cuando el voltaje se mantiene fijo."},
    {q:"¿Cuál es el equivalente de 0.025 A en mA?",options:["2.5 mA","25 mA","250 mA","0.25 mA"],correct:1,why:"1 A = 1000 mA; por tanto 0.025 × 1000 = 25 mA.",wrong:"Para pasar de amperios a miliamperios multiplica por 1000."}
  ]},
  redes:{title:"Serie, paralelo y nodos",meta:"Reducción de redes y leyes de Kirchhoff",questions:[
    {q:"Tres resistencias de 100 Ω, 220 Ω y 330 Ω en serie equivalen a…",options:["650 Ω","57.2 Ω","330 Ω","100 Ω"],correct:0,why:"En serie se suman: 100 + 220 + 330 = 650 Ω. La misma corriente atraviesa cada resistor.",wrong:"El producto dividido por suma corresponde al paralelo de dos resistencias, no a esta red en serie."},
    {q:"Dos resistencias de 1 kΩ en paralelo equivalen a…",options:["2 kΩ","500 Ω","1 kΩ","250 Ω"],correct:1,why:"Dos resistencias iguales en paralelo equivalen a la mitad: 1 kΩ/2 = 500 Ω. El voltaje es igual en las dos ramas.",wrong:"El paralelo de resistencias iguales siempre es menor que cada una; aquí resulta la mitad."},
    {q:"Una fuente de 12 V alimenta 1 kΩ y 2 kΩ en serie. ¿Qué voltaje cae en 2 kΩ?",options:["4 V","8 V","6 V","12 V"],correct:1,why:"Por divisor de voltaje: V₂ = 12 × 2/(1+2) = 8 V, usando kΩ de forma consistente.",wrong:"El voltaje se reparte en proporción a la resistencia: la resistencia de 2 kΩ recibe dos tercios del total."},
    {q:"¿Qué afirma la ley de corrientes de Kirchhoff en un nodo?",options:["La suma de corrientes que entran iguala la que sale","La suma de voltajes siempre es positiva","La corriente es igual en todas las ramas paralelas","La potencia neta es cero en cada resistor"],correct:0,why:"La conservación de carga implica que la suma algebraica de corrientes en un nodo es cero; entrantes y salientes se equilibran.",wrong:"La LCK se refiere a las corrientes en un nodo. La suma de voltajes en una trayectoria cerrada corresponde a la LVK."}
  ]},
  equivalentes:{title:"Thévenin y Norton",meta:"Equivalentes, cortocircuito y carga",questions:[
    {q:"¿Qué representa la corriente de Norton Iₙ?",options:["La corriente de cortocircuito en las terminales de salida","La corriente que atraviesa siempre la carga","El voltaje de circuito abierto","La resistencia vista desde la fuente"],correct:0,why:"Iₙ se obtiene cortocircuitando las terminales de salida con la carga retirada. Su sentido de referencia debe quedar definido.",wrong:"El voltaje de circuito abierto define Vₜₕ. Iₙ corresponde a la corriente de cortocircuito."},
    {q:"Una red tiene Vₜₕ = 12 V y Rₜₕ = 6 Ω. ¿Cuál es Iₙ?",options:["2 A","72 A","0.5 A","6 A"],correct:0,why:"La transformación de fuentes da Iₙ = Vₜₕ/Rₜₕ = 12/6 = 2 A. La resistencia se mantiene igual en ambos equivalentes.",wrong:"Divide Vₜₕ entre Rₜₕ para transformar la fuente de voltaje en fuente de corriente."},
    {q:"En el ejemplo con cuatro resistencias de 330 Ω, ¿cuánto vale Rₙ visto desde RL?",options:["495 Ω","660 Ω","330 Ω","165 Ω"],correct:0,why:"Al desactivar la fuente de voltaje, R1 y R2 quedan en paralelo: 165 Ω. Ese equivalente queda en serie con R3: 165 + 330 = 495 Ω.",wrong:"Recuerda apagar la fuente independiente de voltaje reemplazándola por un corto. El equivalente R1∥R2 queda en serie con R3."},
    {q:"Con Iₙ = 10 mA, Rₙ = 500 Ω y RL = 500 Ω, ¿cuál es la corriente en la carga?",options:["5 mA","10 mA","2.5 mA","20 mA"],correct:0,why:"Divisor de corriente: Iᴸ = Iₙ·Rₙ/(Rₙ+RL) = 10 mA·500/1000 = 5 mA. Dos ramas iguales dividen por igual la corriente.",wrong:"En el modelo Norton, aplica divisor de corriente. Con resistencias de rama iguales la corriente se divide en partes iguales."}
  ]},
  ac:{title:"CA, fasores y transitorios",meta:"Impedancia, fase y constante de tiempo",questions:[
    {q:"¿Cuál es la impedancia de un resistor ideal de 220 Ω en fasores?",options:["220∠0° Ω","220∠90° Ω","j220 Ω","1/220 Ω"],correct:0,why:"La impedancia resistiva es real: Zᴿ = R = 220 + j0 Ω, equivalente a 220∠0° Ω.",wrong:"La impedancia puramente resistiva no tiene parte imaginaria ni desfase entre voltaje y corriente."},
    {q:"Para R = 3 Ω en serie con Xᴸ = 4 Ω, ¿cuál es |Z|?",options:["5 Ω","7 Ω","1 Ω","12 Ω"],correct:0,why:"Z = 3 + j4 Ω; su magnitud es √(3²+4²) = 5 Ω.",wrong:"En serie se suman las impedancias complejas, pero para la magnitud usa Pitágoras entre la parte real e imaginaria."},
    {q:"Un circuito RC tiene R = 10 kΩ y C = 100 μF. ¿Cuál es τ?",options:["1 s","0.1 s","10 s","1000 s"],correct:0,why:"τ = RC = 10 000 × 100×10⁻⁶ = 1 s. Convierte microfaradios a faradios antes de multiplicar.",wrong:"Usa τ = RC y convierte 100 μF a 0.0001 F."},
    {q:"Al aumentar la frecuencia, la reactancia capacitiva Xᴄ…",options:["Disminuye","Aumenta","No cambia","Se vuelve igual a R"],correct:0,why:"Xᴄ = 1/(2πfC). Al aumentar f, el denominador crece y la reactancia capacitiva disminuye.",wrong:"La frecuencia aparece en el denominador de Xᴄ; más frecuencia implica menor reactancia capacitiva."}
  ]}
};

function completedCount(){return chapters.filter(c=>state.completed[c.id]).length}
function humanDate(value){try{return new Intl.DateTimeFormat("es-MX",{day:"numeric",month:"short",year:"numeric"}).format(new Date(value));}catch(e){return ""}}
function toast(msg){const t=$("#toast");if(!t)return;t.textContent=msg;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2100)}
function updateProgress(){const n=completedCount(),pct=Math.round(100*n/chapters.length);$("#side-progress-label").textContent=`${pct}%`;$("#side-progress-bar").style.width=`${pct}%`;$("#side-progress-meta").textContent=`${n} de ${chapters.length} capítulos`}
function viewTitle(v){return {home:"Inicio",simulator:"Simulador",learn:"Aprender",exams:"Exámenes"}[v]||"Inicio"}
function render(){
  $("#crumb-current").textContent=viewTitle(state.view);$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===state.view));updateProgress();
  const now=new Date();$("#today-label").textContent=new Intl.DateTimeFormat("es-MX",{weekday:"short",day:"numeric",month:"short"}).format(now).replace(".","").toUpperCase();
  const root=$("#app-content");if(state.view==="simulator")root.innerHTML=renderSimulator();else if(state.view==="learn")root.innerHTML=renderLearn();else if(state.view==="exams")root.innerHTML=renderExams();else root.innerHTML=renderHome();
}
function changeView(v){state.view=v;saveState();render();window.scrollTo(0,0)}

function renderHome(){
 const n=completedCount(),pct=Math.round(n/chapters.length*100),solved=Object.keys(state.chapterResults).length,examEntries=Object.values(state.bestScores),best=examEntries.length?Math.max(...examEntries):null;
 const resume=chapters.find(c=>!state.completed[c.id])||chapters[0],last=Object.entries(state.chapterResults).sort((a,b)=>new Date(b[1].date)-new Date(a[1].date))[0];
 const cards=chapters.slice(0,3).map(c=>`<article class="chapter-card" data-chapter="${c.id}"><div class="chapter-icon">${c.icon}</div><span class="tag">${c.level}</span><h3>${c.title}</h3><p>${c.desc}</p></article>`).join("");
 return `<section class="hero-card"><div class="hero-copy"><div class="hero-kicker">TU TALLER DE ELECTRICIDAD</div><h1>La teoría cobra sentido cuando la pones a prueba.</h1><p>Aprende análisis de circuitos paso a paso. Construye, mide, practica y entiende cada resultado.</p><button class="primary-btn" data-view="learn">Continuar aprendiendo <span class="btn-arrow">→</span></button></div><div class="hero-art"><svg viewBox="0 0 330 150" role="img" aria-label="Diagrama esquemático de un circuito"><path class="hero-circuit" d="M24 76h54m0 0 13-19 15 38 15-38 15 38 14-19h60m0 0v-40h48m-48 40v42h48m0-82v82m0-82h24m-24 82h24"/><circle class="hero-node" cx="24" cy="76" r="3"/><circle class="hero-node" cx="150" cy="76" r="3"/><circle class="hero-node" cx="228" cy="76" r="3"/><rect class="hero-r" x="260" y="22" width="27" height="30" rx="4"/><rect class="hero-r" x="260" y="101" width="27" height="30" rx="4"/><text class="hero-label" x="87" y="48">R₁</text><text class="hero-label" x="267" y="17">R₂</text><text class="hero-label" x="267" y="145">R₃</text><text class="hero-label" x="7" y="97">Vₛ</text></svg></div></section>
 <section class="dashboard-stats"><div class="stat-card"><div class="stat-top"><span>Capítulos completados</span><i class="stat-symbol">▤</i></div><div class="stat-value">${n}<small> / ${chapters.length}</small></div></div><div class="stat-card"><div class="stat-top"><span>Ejercicios resueltos</span><i class="stat-symbol">✓</i></div><div class="stat-value">${solved}<small> guardados</small></div></div><div class="stat-card"><div class="stat-top"><span>Exámenes realizados</span><i class="stat-symbol">◷</i></div><div class="stat-value">${state.examAttempts||0}</div></div><div class="stat-card"><div class="stat-top"><span>Mejor resultado</span><i class="stat-symbol">↗</i></div><div class="stat-value">${best===null?"—":best}<small>${best===null?" por comenzar":"%"}</small></div></div></section>
 <section class="dashboard-grid"><div><div class="section-heading"><h2>Continúa tu ruta</h2><button class="text-link" data-view="learn">Ver todos los capítulos →</button></div><div class="resume-card"><div class="resume-thumb"><svg viewBox="0 0 120 90" fill="none" aria-hidden="true"><path d="M15 45h22m0 0 8-13 11 26 10-26 10 26 9-13h20M37 45V20h22m0 0v50h26m0-50h20m-20 50h20" stroke="#6d9c82" stroke-width="1.5"/><circle cx="37" cy="45" r="3" fill="#168265"/><rect x="54" y="15" width="13" height="10" rx="2" stroke="#168265"/><rect x="78" y="65" width="13" height="10" rx="2" stroke="#168265"/><text x="40" y="13" font-size="7" fill="#87988c">R1</text><text x="78" y="59" font-size="7" fill="#87988c">RL</text></svg></div><div class="resume-copy"><div class="resume-topline">${resume.level} · ${resume.minutes} MIN</div><h3>${resume.title}</h3><p>${resume.desc}</p><div class="resume-foot"><div class="progress-track"><i style="width:${state.completed[resume.id]?100:0}%"></i></div><span>${state.completed[resume.id]?"Completado":"Siguiente capítulo"}</span><button class="primary-btn" data-chapter="${resume.id}">Abrir <span>→</span></button></div></div></div><div class="section-heading" style="margin-top:23px"><h2>Empieza por aquí</h2><button class="text-link" data-view="learn">Explorar ruta →</button></div><div class="chapter-row">${cards}</div></div><div><div class="section-heading"><h2>Tu progreso</h2></div><div class="progress-card"><div class="progress-card-head"><div><h3>Ruta de análisis de circuitos</h3><span class="muted">Aprende a tu ritmo</span></div><span class="tag">EN CURSO</span></div><div class="ring-wrap"><div class="progress-ring"><svg viewBox="0 0 70 70"><circle cx="35" cy="35" r="30"/><circle class="ring-value" cx="35" cy="35" r="30" style="stroke-dashoffset:${188-(188*pct/100)}"/></svg><div class="ring-number">${pct}%</div></div><div class="ring-copy"><b>${n} de ${chapters.length} capítulos</b><span>Una idea a la vez.<br>Vas construyendo criterio.</span></div></div><div class="progress-card-foot"><span>Práctica completada</span><b>${solved} ejercicio${solved===1?"":"s"}</b></div></div><div class="section-heading" style="margin-top:20px"><h2>Último resultado</h2></div>${last?`<div class="progress-card"><div class="resume-topline">${esc(chapters.find(c=>c.id===last[0])?.title||"PRÁCTICA")}</div><h3 style="margin:5px 0 6px">${esc(last[1].answer)} ${esc(last[1].unit||"")}</h3><div class="muted small">Resuelto el ${humanDate(last[1].date)}</div><button class="text-link" style="padding-left:0;margin-top:7px" data-chapter="${last[0]}">Repasar procedimiento →</button></div>`:`<div class="progress-card"><p class="muted small" style="line-height:1.6;margin:0">Al resolver tu primer ejercicio, aquí quedará el resultado junto con el procedimiento que escribiste.</p></div>`}</div></section>`;
}

function componentTypeLabel(type){return {R:"Resistencia",V:"Fuente V",I:"Fuente I",W:"Cable ideal"}[type]||type}
function componentValueLabel(c){if(c.type==="W")return "—";if(c.type==="I"&&Math.abs(Number(c.value))<1)return `${fmtNum(Number(c.value)*1000)} mA`;return `${fmtNum(Number(c.value))} ${c.unit}`}
function fmtNum(x,d=3){if(!Number.isFinite(Number(x)))return "—";if(Math.abs(x)<1e-12)return "0";return Number(x).toLocaleString("es-MX",{maximumFractionDigits:d})}
function formatSI(value,unit){if(!Number.isFinite(value))return "—";const a=Math.abs(value);if(value===0)return `0 ${unit}`;if(a>=1e6)return `${fmtNum(value/1e6)} M${unit}`;if(a>=1e3&&unit!=="Ω")return `${fmtNum(value/1e3)} k${unit}`;if(a>=1e3&&unit==="Ω")return `${fmtNum(value/1e3)} kΩ`;if(a>=1)return `${fmtNum(value)} ${unit}`;if(a>=1e-3)return `${fmtNum(value*1e3)} m${unit}`;if(a>=1e-6)return `${fmtNum(value*1e6)} μ${unit}`;return `${value.toExponential(2)} ${unit}`}
function solveCircuit(components){
 const parent={};nodeNames.forEach(n=>parent[n]=n);const find=x=>parent[x]===x?x:(parent[x]=find(parent[x]));const union=(a,b)=>{const x=find(a),y=find(b);if(x!==y)parent[x]=y};
 components.filter(c=>c.type==="W").forEach(c=>union(c.n1,c.n2));
 const ground=find("0"), roots=[...new Set(nodeNames.map(find))].filter(r=>r!==ground), idx={};roots.forEach((n,i)=>idx[n]=i);
 const volts=components.filter(c=>c.type==="V"),N=roots.length+volts.length;if(N===0)return {ok:true,voltages:{"0":0},elements:{},totalPower:0};
 const A=Array.from({length:N},()=>Array(N).fill(0)),z=Array(N).fill(0);const ni=n=>{const r=find(n);return r===ground?-1:idx[r]};
 const stampG=(a,b,g)=>{const i=ni(a),j=ni(b);if(i>=0)A[i][i]+=g;if(j>=0)A[j][j]+=g;if(i>=0&&j>=0){A[i][j]-=g;A[j][i]-=g}};
 for(const c of components){const i=ni(c.n1),j=ni(c.n2),v=Number(c.value);if(c.type==="R"){if(!(v>0))return {ok:false,error:`${c.name} debe tener una resistencia mayor que cero.`};stampG(c.n1,c.n2,1/v)}else if(c.type==="I"){if(i>=0)z[i]-=v;if(j>=0)z[j]+=v}}
 volts.forEach((c,k)=>{const i=ni(c.n1),j=ni(c.n2),b=roots.length+k;if(i===j&&Math.abs(Number(c.value))>1e-12)return; if(i>=0){A[i][b]+=1;A[b][i]+=1}if(j>=0){A[j][b]-=1;A[b][j]-=1}z[b]=Number(c.value)});
 const M=A.map((row,i)=>[...row,z[i]]);
 for(let col=0;col<N;col++){let pivot=col;for(let r=col+1;r<N;r++)if(Math.abs(M[r][col])>Math.abs(M[pivot][col]))pivot=r;if(Math.abs(M[pivot][col])<1e-12)return {ok:false,error:"La red no tiene una solución DC única. Revisa nodos sin referencia, fuentes ideales en corto o lazos de fuentes incompatibles."};[M[col],M[pivot]]=[M[pivot],M[col]];const d=M[col][col];for(let j=col;j<=N;j++)M[col][j]/=d;for(let r=0;r<N;r++){if(r===col)continue;const f=M[r][col];if(Math.abs(f)<1e-18)continue;for(let j=col;j<=N;j++)M[r][j]-=f*M[col][j]}}
 const sol=M.map(r=>r[N]),voltages={};for(const n of nodeNames){const i=ni(n);voltages[n]=i<0?0:sol[i]}
 const elements={};let totalPower=0;
 for(const c of components){const vdrop=voltages[c.n1]-voltages[c.n2];let current=null,power=null;if(c.type==="R"){current=vdrop/Number(c.value);power=vdrop*current;totalPower+=power}else if(c.type==="V"){current=sol[roots.length+volts.findIndex(x=>x.id===c.id)];power=vdrop*current}else if(c.type==="I"){current=Number(c.value);power=vdrop*current}else if(c.type==="W"){current=null;power=0}elements[c.id]={v:vdrop,i:current,p:power}}
 return {ok:true,voltages,elements,totalPower};
}

function branchSymbol(c,x1,y1,x2,y2,orientation,labelY){
 const isH=orientation==="h",cx=(x1+x2)/2,cy=(y1+y2)/2;let s="";
 if(c.type==="R"){if(isH){let pts=[];for(let i=0;i<=8;i++){const x=cx-25+i*6.25, y=cy+(i===0||i===8?0:(i%2? -7:7));pts.push(`${i?"L":"M"}${x} ${y}`)}s+=`<path class="svg-wire" d="M${x1} ${y1}H${cx-25}"/><path class="svg-part" d="${pts.join(" ")}"/><path class="svg-wire" d="M${cx+25} ${cy}H${x2}"/>`}else{let pts=[];for(let i=0;i<=8;i++){const y=cy-25+i*6.25,x=cx+(i===0||i===8?0:(i%2? -7:7));pts.push(`${i?"L":"M"}${x} ${y}`)}s+=`<path class="svg-wire" d="M${x1} ${y1}V${cy-25}"/><path class="svg-part" d="${pts.join(" ")}"/><path class="svg-wire" d="M${cx} ${cy+25}V${y2}"/>`}}
 else if(c.type==="V"||c.type==="I"){s+=`<path class="svg-wire" d="M${x1} ${y1}L${isH?cx-19:cx} ${isH?cy:cy-19}"/><circle class="svg-source" cx="${cx}" cy="${cy}" r="18"/><path class="svg-wire" d="M${isH?cx+19:cx} ${isH?cy:cy+19}L${x2} ${y2}"/>`;if(c.type==="V")s+=`<text class="svg-source-text" text-anchor="middle" x="${cx}" y="${cy+3}">+ −</text>`;else s+=`<path class="svg-current" d="M${cx-8} ${cy}H${cx+7}m-4-4 4 4-4 4"/>`}
 else{s+=`<path class="svg-wire" d="M${x1} ${y1}L${x2} ${y2}"/><circle cx="${cx}" cy="${cy}" r="3" fill="#198263"/>`}
 const text=`${esc(c.name)} · ${esc(componentValueLabel(c))}`;s+=orientation==="h"?`<text class="svg-small" text-anchor="middle" x="${cx}" y="${labelY}">${text}</text>`:`<text class="svg-small" text-anchor="start" x="${cx+39}" y="${cy+3}">${text}</text>`;return s;
}
function circuitSvg(){
 const xs={N1:150,N2:430,N3:710},top=86,rail=390;let s=`<svg class="circuit-svg" viewBox="0 0 860 470" role="img" aria-label="Circuito DC editable con nodos y componentes"><path class="svg-wire" d="M110 ${rail}H760"/><path class="svg-ground" d="M130 ${rail}v9m-13 0h26m-9 5h-8m-5 5h18"/><text class="svg-small" x="108" y="${rail-9}">0 · GND</text>`;
 for(const n of ["N1","N2","N3"])s+=`<circle class="svg-node" cx="${xs[n]}" cy="${top}" r="4"/><text class="svg-label" x="${xs[n]-11}" y="${top-13}">${n}</text>`;
 const groups={};for(const c of state.components){const a=c.n1==="0"?"0":c.n1,b=c.n2==="0"?"0":c.n2,key=[a,b].sort().join("-");groups[key]=(groups[key]||0)+1}
 const seen={};for(const c of state.components){const a=c.n1,b=c.n2,key=[a,b].sort().join("-");const k=seen[key]||0;seen[key]=k+1;let y1,y2,x1,x2,labelY;
   if(a==="0"||b==="0"){const n=a==="0"?b:a,base=xs[n]||430,offset=(k-(groups[key]-1)/2)*48;const x=base+offset;y1=top;y2=rail;x1=x;x2=x;labelY=207+k*48;s+=`<path class="svg-wire" d="M${base} ${top}H${x}M${base} ${top}V${top-3}"/>`;s+=branchSymbol(c,x1,y1,x2,y2,"v",labelY)}
   else{const xa=xs[a]||150,xb=xs[b]||710,ya=top+k*56,yb=top+k*56;y1=ya;y2=yb;x1=xa;x2=xb;labelY=ya-15;s+=`<path class="svg-wire" d="M${xa} ${top}V${ya}M${xb} ${top}V${yb}"/>`;s+=branchSymbol(c,x1,y1,x2,y2,"h",labelY)}
 }
 s+=`<text class="svg-small" x="638" y="426">${state.components.length} elementos · análisis nodal DC</text></svg>`;return s;
}
function renderSimulator(){
 const names=state.components.map(c=>c.name);const solution=state.lastSolution;const error=solution&&!solution.ok?solution.error:"";
 const rows=state.components.map(c=>`<tr data-component-row="${c.id}"><td><span class="part-type">${c.type==="W"?"⌁":c.type}</span> <span class="mono">${esc(c.name)}</span></td><td>${c.type==="W"?`<span class="muted">Cable ideal</span>`:`<div style="display:flex;align-items:center;gap:5px"><input class="field-mini" style="max-width:90px" type="number" step="any" value="${esc(c.value)}" data-component-value="${c.id}" aria-label="Valor de ${esc(c.name)}"><span class="muted small">${esc(c.unit)}</span></div>`}</td><td><select class="select-mini" data-node="${c.id}:n1" aria-label="Terminal inicial de ${esc(c.name)}">${nodeOptions(c.n1)}</select></td><td><select class="select-mini" data-node="${c.id}:n2" aria-label="Terminal final de ${esc(c.name)}">${nodeOptions(c.n2)}</select></td><td><button class="component-delete" data-remove-component="${c.id}" title="Eliminar ${esc(c.name)}">×</button></td></tr>`).join("");
 const selectable=state.components.filter(c=>c.type!=="W");const currentId=selectable.some(c=>c.id===state.meterComponent)?state.meterComponent:(selectable[0]?.id||"");state.meterComponent=currentId;
 let reading="Ejecuta una simulación",readingNote="Las medidas aparecerán aquí.";
 const mode=state.meterMode||"voltage";
 if(solution?.ok||mode==="resistance"){
   if(mode==="voltage"){const a=state.meterA||"N2",b=state.meterB||"0";reading=formatSI((solution.voltages[a]||0)-(solution.voltages[b]||0),"V");readingNote=`${a} respecto a ${b}`}
   else{const c=selectable.find(x=>x.id===currentId),e=c&&solution?.elements?.[c.id];if(c){if(mode==="current"){reading=e?.i===null?"No definida":formatSI(e?.i,"A");readingNote=`${c.name}: sentido de ${c.n1} hacia ${c.n2}`}else if(mode==="power"){reading=formatSI(e?.p??0,"W");readingNote=`${c.name}: potencia absorbida (+) o entregada (−)`}else{reading=c.type==="R"?formatSI(Number(c.value),"Ω"):"Ideal / no aplica";readingNote=`${c.name}: resistencia nominal del componente`}}}}
 const compOptions=selectable.map(c=>`<option value="${c.id}" ${c.id===currentId?"selected":""}>${esc(c.name)} · ${componentTypeLabel(c.type)}</option>`).join("");
 return `<div class="sim-top"><div><div class="eyebrow">LABORATORIO VIRTUAL · DC</div><h1>Simulador de circuitos</h1><div class="sim-status"><i class="status-dot"></i>${solution?.ok?"Simulación lista":"Edición pendiente"} · análisis nodal</div></div><div class="sim-actions">${state.savedCircuit?`<button class="secondary-btn" data-action="load-circuit">Cargar guardado</button>`:""}<button class="secondary-btn" data-action="save-circuit">Guardar circuito</button><button class="primary-btn" data-action="solve-circuit">▶ &nbsp; Simular</button></div></div>
 <div class="sim-layout"><div><section class="panel"><div class="panel-head"><h3>Espacio de diseño</h3><span>Red de ejemplo · equivalente de Norton</span></div><div class="canvas-toolbar"><button class="tool-btn" data-add-component="R"><i>⌁</i> Resistencia</button><button class="tool-btn" data-add-component="V"><i>⊕</i> Fuente V</button><button class="tool-btn" data-add-component="I"><i>↗</i> Fuente I</button><button class="tool-btn" data-add-component="W"><i>—</i> Cable</button><span class="tool-spacer"></span><button class="tool-btn" data-action="reset-circuit">Restaurar ejemplo</button></div><div class="circuit-wrap">${circuitSvg()}</div><div class="circuit-caption">Edita valores y nodos en la tabla. Elementos con el mismo nombre de nodo están eléctricamente conectados.</div></section>
 <section class="panel editor-panel"><div class="panel-head"><h3>Componentes y conexiones</h3><span>Haz clic en un valor o nodo para editar</span></div><table class="component-table"><thead><tr><th>ELEMENTO</th><th>VALOR</th><th>NODO +</th><th>NODO −</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="5" class="muted">Añade un componente para empezar.</td></tr>`}</tbody></table></section>${solution?.ok?`<section class="panel editor-panel"><div class="panel-head"><h3>Mediciones calculadas</h3><span>Convención de corriente: nodo + → nodo −</span></div><table class="component-table"><thead><tr><th>ELEMENTO</th><th>CAÍDA ΔV</th><th>CORRIENTE</th><th>POTENCIA</th></tr></thead><tbody>${state.components.map(c=>{const e=solution.elements[c.id];return `<tr><td><span class="mono">${esc(c.name)}</span></td><td class="mono">${formatSI(e.v,"V")}</td><td class="mono">${e.i===null?"—":formatSI(e.i,"A")}</td><td class="mono">${formatSI(e.p,"W")}</td></tr>`}).join("")}</tbody></table></section>`:""}</div>
 <aside class="sim-side"><section class="panel meter-panel"><div class="meter-title"><h3>Multímetro</h3><span class="meter-icon">⌁</span></div><label class="form-label" for="meter-mode">Modo de medición</label><select id="meter-mode" class="form-control"><option value="voltage" ${(state.meterMode||"voltage")==="voltage"?"selected":""}>Voltaje entre nodos</option><option value="current" ${state.meterMode==="current"?"selected":""}>Corriente del elemento</option><option value="power" ${state.meterMode==="power"?"selected":""}>Potencia del elemento</option><option value="resistance" ${state.meterMode==="resistance"?"selected":""}>Resistencia nominal</option></select>${(state.meterMode||"voltage")==="voltage"?`<div style="display:grid;grid-template-columns:1fr 1fr;gap:7px"><div><label class="form-label">Punta roja</label><select id="meter-a" class="form-control">${nodeOptions(state.meterA||"N2")}</select></div><div><label class="form-label">Punta negra</label><select id="meter-b" class="form-control">${nodeOptions(state.meterB||"0")}</select></div></div>`:`<label class="form-label" for="meter-component">Elemento</label><select id="meter-component" class="form-control">${compOptions}</select>`}<div class="meter-reading"><div class="reading-label">Lectura</div><div class="reading-value">${esc(reading)}</div><div class="reading-note">${esc(readingNote)}</div></div>${error?`<div class="error-box">${esc(error)}</div>`:""}</section>
 <section class="panel results-panel"><h3>Resumen de simulación</h3>${solution?.ok?`<div class="result-line"><span>Potencia en resistencias</span><b>${formatSI(solution.totalPower,"W")}</b></div><div class="result-line"><span>Voltaje en N1</span><b>${formatSI(solution.voltages.N1||0,"V")}</b></div><div class="result-line"><span>Voltaje en N2</span><b>${formatSI(solution.voltages.N2||0,"V")}</b></div><div class="result-line"><span>Voltaje en N3</span><b>${formatSI(solution.voltages.N3||0,"V")}</b></div>`:`<div class="muted small" style="line-height:1.6">Pulsa Simular para resolver voltajes nodales, corrientes de rama y potencia.</div>`}</section><div class="help-mini"><b>¿Cómo medir?</b>Elige voltaje y define las puntas del multímetro. Para corriente y potencia, selecciona un componente. El signo muestra la referencia de medición.</div><p class="sim-note"><strong>Modelo DC ideal.</strong> El análisis usa resistencias, fuentes ideales independientes y cables ideales. Los resultados son de estado estacionario.</p></aside></div>`;
}

function renderLearn(){
 const ch=chapters.find(c=>c.id===state.activeChapter)||chapters[0];state.activeChapter=ch.id;const idx=chapters.indexOf(ch)+1;const result=state.chapterResults[ch.id];const progress=chapters.map((c,i)=>`<button class="lesson-nav-item ${c.id===ch.id?"active":""}" data-chapter="${c.id}"><span class="lesson-num">${String(i+1).padStart(2,"0")}</span><span>${c.short}</span>${state.completed[c.id]?`<i class="done-check">✓</i>`:""}</button>`).join("");
 return `<div class="page-heading"><div><div class="eyebrow">RUTA GUIADA · ${chapters.length} CAPÍTULOS</div><h1>Aprender análisis de circuitos</h1><p class="lede">Teoría esencial, circuitos de práctica y pistas para que avances con confianza.</p></div><button class="secondary-btn" data-view="simulator">Abrir simulador <span class="btn-arrow">↗</span></button></div><div class="learn-layout"><aside class="panel lesson-nav"><div class="lesson-nav-head">CONTENIDO DEL CURSO</div>${progress}<div class="lesson-nav-foot">Completa el ejercicio de cada capítulo para guardar el resultado y marcar tu avance.</div></aside><div class="lesson-main"><section class="lesson-hero"><div><div class="eyebrow">CAPÍTULO ${String(idx).padStart(2,"0")} · ${ch.level} · ${ch.minutes} MIN</div><h2>${ch.title}</h2><p>${ch.desc}</p></div><div class="lesson-number">${String(idx).padStart(2,"0")}</div></section><section class="lesson-panel"><h3>Idea clave</h3><div class="theory-copy">${ch.theory}</div><div class="formula-block"><small>RELACIÓN CLAVE</small>${ch.formula}</div><div class="lesson-callout">${ch.callout}</div></section><section class="exercise-card"><div class="exercise-top"><h3>Practica lo aprendido</h3><span class="difficulty">EJERCICIO GUIADO</span></div><p class="exercise-prompt">${ch.question}</p><label class="form-label" for="procedure-input">Tu procedimiento <span class="muted">· puedes escribir símbolos y fracciones</span></label><div class="equation-toolbar" aria-label="Insertar símbolo"><button class="math-tool" data-insert="\\frac{}{}" title="Insertar fracción">a⁄b</button><button class="math-tool" data-insert="×">×</button><button class="math-tool" data-insert="÷">÷</button><button class="math-tool" data-insert="Ω">Ω</button><button class="math-tool" data-insert="μ">μ</button><button class="math-tool" data-insert="√{}">√</button><button class="math-tool" data-insert="∥">∥</button><button class="math-tool" data-insert="π">π</button><button class="math-tool" data-insert="∠">∠</button><button class="math-tool" data-insert="^2">x²</button></div><textarea id="procedure-input" class="math-input" placeholder="Escribe tus pasos aquí…">${esc(state.drafts[ch.id]||"")}</textarea><div class="math-preview"><span class="math-preview-label">VISTA</span><span class="rendered-math" id="math-preview">${formatMath(state.drafts[ch.id]||"")||"Tu expresión aparecerá aquí."}</span></div><div class="practice-bottom"><div class="answer-wrap"><label class="form-label" for="answer-input">Resultado final <span class="muted">(${ch.unit})</span></label><input id="answer-input" class="answer-input" type="text" inputmode="decimal" placeholder="Escribe el valor en ${esc(ch.unit)}" value="${esc(state.answerDraft||"")}"></div><button class="secondary-btn hint-btn" data-action="show-hint">💡 &nbsp; Pista <span>${(state.hintIndex||0)+1}</span></button><button class="primary-btn" data-action="check-answer">Comprobar <span class="btn-arrow">→</span></button></div>${state.hintIndex?`<div class="hint-box"><b>Pista ${Math.min(state.hintIndex,ch.hints.length)}:</b> ${esc(ch.hints[Math.min(state.hintIndex,ch.hints.length)-1])}</div>`:""}${state.exerciseFeedback?`<div class="feedback-box ${state.exerciseFeedback.good?"good":"bad"}">${state.exerciseFeedback.html}</div>`:""}${result?`<div class="saved-result"><div class="saved-result-head"><b>✓ Resultado guardado</b><small>${humanDate(result.date)}</small></div><div style="margin-top:5px">Resultado: <b>${esc(result.answer)} ${esc(result.unit)}</b>${result.procedure?`<br>Procedimiento: ${esc(result.procedure).replace(/\n/g," · ")}`:""}</div></div>`:""}</section><div style="display:flex;justify-content:space-between;margin-top:12px"><button class="quiet-btn" data-chapter="${chapters[Math.max(0,idx-2)].id}" ${idx===1?"disabled":""}>← Capítulo anterior</button><button class="quiet-btn" data-chapter="${chapters[Math.min(chapters.length-1,idx)].id}" ${idx===chapters.length?"disabled":""}>Siguiente capítulo →</button></div></div></div>`;
}
function formatMath(text){if(!text)return "";let s=esc(text).replace(/\\frac\{([^{}]*)\}\{([^{}]*)\}/g,`<span class="fraction"><span class="num">$1</span><span class="den">$2</span></span>`);s=s.replace(/\\sqrt\{([^{}]*)\}/g,"√<span class=\"fraction\"><span class=\"num\">$1</span></span>").replace(/\\times/g,"×").replace(/\\cdot/g,"·").replace(/\\Omega/g,"Ω").replace(/\\mu/g,"μ").replace(/\\pi/g,"π").replace(/\\angle/g,"∠").replace(/\\parallel/g,"∥").replace(/\^([0-9]+)/g,"<sup>$1</sup>").replace(/\n/g,"<br>");return s;}

function renderExams(){
 const exam=state.exam;const topicKeys=Object.keys(examBanks);const scores=Object.values(state.bestScores);const avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):null;
 const side=`<aside class="exam-side"><section class="panel exam-side-card"><h3>Tu historial</h3><div class="exam-score">${state.examAttempts||0}</div><p>examen${state.examAttempts===1?"":"es"} completado${state.examAttempts===1?"":"s"}</p><div class="score-track"><i style="width:${avg??0}%"></i></div><p>Mejor promedio de tema <b>${avg===null?"—":avg+"%"}</b></p></section><section class="panel exam-side-card"><h3>Un examen útil</h3><p>Responde sin prisa. Después de cada selección verás por qué la opción es correcta y qué idea revisar si elegiste otra.</p></section></aside>`;
 let main="";
 if(!exam.started&&!exam.finished){main=`<section class="panel exam-card"><div class="eyebrow">ELIGE UNA RUTA</div><h3 style="margin-top:8px">¿Qué tema quieres practicar?</h3><p class="muted small">Cada simulación contiene cuatro preguntas con explicación detallada.</p><div class="topic-grid">${topicKeys.map(k=>`<button class="topic-choice ${exam.topic===k?"selected":""}" data-exam-topic="${k}"><b>${examBanks[k].title}</b><span>${examBanks[k].meta} · 4 preguntas</span></button>`).join("")}</div><button class="primary-btn" data-action="start-exam">Comenzar simulación <span class="btn-arrow">→</span></button></section>`}
 else if(exam.finished){const bank=examBanks[exam.topic],correct=exam.answers.filter(a=>a===true).length,pct=Math.round(correct/bank.questions.length*100);main=`<section class="panel exam-card"><div class="eyebrow">SIMULACIÓN COMPLETADA</div><h3 style="font-size:17px;margin:9px 0 3px">${bank.title}</h3><div class="exam-score">${pct}%</div><p class="muted small">${correct} de ${bank.questions.length} respuestas correctas. ${pct===100?"Dominaste este bloque.":pct>=75?"Buen trabajo; revisa las explicaciones para afianzar." : "Vuelve a la teoría y prueba otra vez: cada error te muestra qué concepto reforzar."}</p><div style="display:flex;gap:8px;margin-top:14px"><button class="primary-btn" data-action="retake-exam">Intentar de nuevo</button><button class="secondary-btn" data-action="exit-exam">Elegir otro tema</button></div></section>`}
 else {const bank=examBanks[exam.topic],q=bank.questions[exam.q],selected=exam.selected,checked=selected!==null;main=`<section class="panel exam-card"><div class="eyebrow">${esc(bank.title)} · SIMULACIÓN</div><div class="exam-control-row" style="padding-top:0;border:0;margin-top:8px"><span class="exam-progress-label">PREGUNTA ${exam.q+1} DE ${bank.questions.length}</span><span class="exam-progress-label">${Math.round(exam.q/bank.questions.length*100)}% COMPLETADO</span></div><div class="score-track"><i style="width:${Math.round(exam.q/bank.questions.length*100)}%"></i></div><p class="exam-question">${q.q}</p><div class="exam-options">${q.options.map((o,i)=>`<button class="exam-option ${checked?(i===q.correct?"correct":i===selected?"wrong":""):i===selected?"chosen":""}" data-exam-answer="${i}" ${checked?"disabled":""}><span class="option-letter">${String.fromCharCode(65+i)}</span>${o}</button>`).join("")}</div>${checked?`<div class="exam-rationale ${selected===q.correct?"good":"bad"}"><h4>${selected===q.correct?"¡Correcto! Así se resuelve:":"Revisa este paso a paso"}</h4><p>${selected!==q.correct?`Elegiste <b>${esc(q.options[selected])}</b>. ${esc(q.wrong)}<br><br>`:""}${esc(q.why)}</p></div>`:""}<div class="exam-control-row"><span class="exam-progress-label">${checked?(selected===q.correct?"Respuesta acertada":"Respuesta por revisar"):"Selecciona una opción"}</span>${checked?`<button class="primary-btn" data-action="exam-next">${exam.q===bank.questions.length-1?"Ver resultados":"Siguiente pregunta"} <span class="btn-arrow">→</span></button>`:`<span class="muted small">La explicación aparece al elegir.</span>`}</div></section>`}
 return `<section class="exam-intro"><div class="exam-intro-copy"><div class="eyebrow">PRÁCTICA CON RETROALIMENTACIÓN</div><h1>Exámenes simulados</h1><p>Elige un tema, pon a prueba lo que sabes y entiende el razonamiento detrás de cada respuesta.</p></div><div class="exam-badge"><b>4</b>PREGUNTAS POR TEMA</div></section><div class="exam-layout"><div>${main}</div>${side}</div>`;
}

function nextId(){let max=0;for(const c of state.components){const n=Number(String(c.id).replace(/\D/g,""));if(n>max)max=n}return `c${max+1}`}
function addComponent(type){const id=nextId(),prefix={R:"R",V:"V",I:"I",W:"W"}[type],used=new Set(state.components.map(c=>c.name));let k=1;while(used.has(`${prefix}${k}`))k++;const c={id,type,name:`${prefix}${k}`,value:type==="R"?1000:type==="V"?5:type==="I"?0.001:0,unit:type==="R"?"Ω":type==="V"?"V":"A",n1:"N2",n2:"0"};if(type==="W"){c.n1="N3";c.n2="0"}state.components.push(c);state.lastSolution=null;saveState();render();toast(`${componentTypeLabel(type)} añadido`)}
function refreshSimulation(){state.lastSolution=solveCircuit(state.components);saveState();render();if(state.lastSolution.ok)toast("Circuito resuelto");else toast("Revisa la topología y las fuentes")}
function parseAnswer(raw){const val=String(raw).trim().replace(/,/g,".").match(/[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/i);return val?Number(val[0]):NaN}
function checkExercise(){const ch=chapters.find(c=>c.id===state.activeChapter)||chapters[0],answer=parseAnswer($("#answer-input")?.value||"");state.answerDraft=$("#answer-input")?.value||"";if(!Number.isFinite(answer)){state.exerciseFeedback={good:false,html:"Escribe un resultado numérico para poder revisarlo."};render();return}const ok=Math.abs(answer-ch.answer)<=Math.max(Math.abs(ch.answer)*.005,.01);if(ok){const procedure=state.drafts[ch.id]||"";state.completed[ch.id]=true;state.chapterResults[ch.id]={answer:fmtNum(answer),unit:ch.unit,procedure,date:new Date().toISOString()};state.exerciseFeedback={good:true,html:`<b>¡Correcto! Tu resultado y procedimiento quedaron guardados.</b><br>${ch.solution.map((line,i)=>`${i+1}. ${esc(line)}`).join("<br>")}`};saveState();render();toast("Ejercicio resuelto y guardado")}else{state.exerciseFeedback={good:false,html:`Todavía no coincide. Revisa las unidades y el signo, y vuelve a intentarlo. Pulsa <b>Pista</b> si quieres una guía paso a paso.`};render()}}

function startExam(){state.exam.started=true;state.exam.finished=false;state.exam.q=0;state.exam.selected=null;state.exam.answers=[];saveState();render()}
function endExam(){const bank=examBanks[state.exam.topic],correct=state.exam.answers.filter(x=>x).length,pct=Math.round(correct/bank.questions.length*100);state.exam.finished=true;state.exam.started=false;state.bestScores[state.exam.topic]=Math.max(state.bestScores[state.exam.topic]||0,pct);state.examAttempts=(state.examAttempts||0)+1;saveState();render()}

$("#app-content").addEventListener("click",e=>{
 const view=e.target.closest("[data-view]");if(view){changeView(view.dataset.view);return}
 const chapter=e.target.closest("[data-chapter]");if(chapter){state.activeChapter=chapter.dataset.chapter;state.exerciseFeedback=null;state.hintIndex=0;state.answerDraft="";state.view="learn";saveState();render();window.scrollTo(0,0);return}
 const add=e.target.closest("[data-add-component]");if(add){addComponent(add.dataset.addComponent);return}
 const remove=e.target.closest("[data-remove-component]");if(remove){state.components=state.components.filter(c=>c.id!==remove.dataset.removeComponent);state.lastSolution=null;saveState();render();return}
 const topic=e.target.closest("[data-exam-topic]");if(topic){state.exam.topic=topic.dataset.examTopic;saveState();render();return}
 const option=e.target.closest("[data-exam-answer]");if(option&&state.exam.selected===null){state.exam.selected=Number(option.dataset.examAnswer);saveState();render();return}
 const insert=e.target.closest("[data-insert]");if(insert){const ta=$("#procedure-input");if(ta){const a=ta.selectionStart,b=ta.selectionEnd;ta.setRangeText(insert.dataset.insert,a,b,"end");ta.focus();state.drafts[state.activeChapter]=ta.value;saveState();const preview=$("#math-preview");if(preview)preview.innerHTML=formatMath(ta.value)||"Tu expresión aparecerá aquí."}return}
 const action=e.target.closest("[data-action]")?.dataset.action;if(!action)return;
 if(action==="solve-circuit"){refreshSimulation()}
 else if(action==="reset-circuit"){state.components=defaultCircuit.map(c=>({...c}));state.lastSolution=solveCircuit(state.components);saveState();render();toast("Ejemplo de Norton restaurado")}
 else if(action==="save-circuit"){state.savedCircuit=state.components.map(c=>({...c}));saveState();render();toast("Circuito guardado en este dispositivo")}
 else if(action==="load-circuit"){if(state.savedCircuit){state.components=state.savedCircuit.map(c=>({...c}));state.lastSolution=solveCircuit(state.components);saveState();render();toast("Circuito guardado cargado")}}
 else if(action==="show-hint"){const ch=chapters.find(c=>c.id===state.activeChapter);state.hintIndex=Math.min((state.hintIndex||0)+1,ch.hints.length);saveState();render()}
 else if(action==="check-answer")checkExercise()
 else if(action==="start-exam")startExam()
 else if(action==="exam-next"){state.exam.answers.push(state.exam.selected===examBanks[state.exam.topic].questions[state.exam.q].correct);if(state.exam.q===examBanks[state.exam.topic].questions.length-1)endExam();else{state.exam.q++;state.exam.selected=null;saveState();render()}}
 else if(action==="retake-exam")startExam()
 else if(action==="exit-exam"){state.exam.finished=false;state.exam.started=false;saveState();render()}
});

$("#app-content").addEventListener("input",e=>{
 if(e.target.id==="procedure-input"){state.drafts[state.activeChapter]=e.target.value;saveState();const preview=$("#math-preview");if(preview)preview.innerHTML=formatMath(e.target.value)||"Tu expresión aparecerá aquí."}
 if(e.target.id==="answer-input"){state.answerDraft=e.target.value;saveState()}
 const id=e.target.dataset.componentValue;if(id){const c=state.components.find(x=>x.id===id);if(c){c.value=Number(e.target.value);state.lastSolution=null;saveState()}}
});
$("#app-content").addEventListener("change",e=>{
 const node=e.target.dataset.node;if(node){const [id,key]=node.split(":");const c=state.components.find(x=>x.id===id);if(c){c[key]=e.target.value;state.lastSolution=null;saveState();render()}return}
 const id=e.target.dataset.componentValue;if(id){const c=state.components.find(x=>x.id===id);if(c)c.value=Number(e.target.value);state.lastSolution=null;saveState();render();return}
 if(e.target.id==="meter-mode"){state.meterMode=e.target.value;saveState();render()}
 else if(e.target.id==="meter-a"){state.meterA=e.target.value;saveState();render()}
 else if(e.target.id==="meter-b"){state.meterB=e.target.value;saveState();render()}
 else if(e.target.id==="meter-component"){state.meterComponent=e.target.value;saveState();render()}
});

document.body.addEventListener("click",e=>{const outsideView=e.target.closest("[data-view]");if(outsideView&&!$("#app-content").contains(outsideView)){changeView(outsideView.dataset.view);return}if(e.target.closest("[data-action='show-help']")){const modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<div class="help-modal"><div class="eyebrow">CIRCUITOS LAB</div><h2>Aprende haciendo</h2><p>En el <b>simulador</b>, añade resistencias, fuentes o cables, cambia valores y asigna nodos. Pulsa Simular para obtener voltajes, corrientes y potencias de una red DC.</p><p>En <b>Aprender</b>, escribe el procedimiento y el resultado. Usa las pistas cuando te atasques; al acertar, la solución queda guardada en este dispositivo.</p><p>En <b>Exámenes</b>, selecciona un tema y responde cuatro preguntas. Cada respuesta muestra una explicación paso a paso.</p><button class="secondary-btn" data-close-help>Cerrar</button></div>`;document.body.appendChild(modal);modal.addEventListener("click",ev=>{if(ev.target===modal||ev.target.closest("[data-close-help]"))modal.remove()})}});

if(state.lastSolution===null){state.lastSolution=solveCircuit(state.components);saveState()}
if(!state.meterMode)state.meterMode="voltage";render();

